\label{SCLES}\emph{(\cite{LSS})}
Let $\mathbbm{k}$ be a field of characteristic zero. For a triple $(A,B,\varepsilon)$, we have the long exact sequence
$$\ldots\xrightarrow{B_*}HH_n(A,B,\varepsilon)\xrightarrow{I_*}HC_n(A,B,\varepsilon)\xrightarrow{S_*}HC_{n-2}(A,B,\varepsilon)\xrightarrow{B_*}HH_{n-1}(A,B,\varepsilon)\xrightarrow{I_*}\ldots$$

\label{HH1AB}
For a commutative triple $\mathcal{T}=(A,B,\varepsilon)$, we have that
$$HH_1(A,B,\varepsilon)\cong\Omega_{\mathcal{T}|\mathbbm{k}}^1.$$

\label{HC1AB}
For a commutative triple $\mathcal{T}=(A,B,\varepsilon)$, we have that
$$HC_1(A,B,\varepsilon)\cong\frac{\Omega_{\mathcal{T}|\mathbbm{k}}^1}{d(1\otimes A)}.$$

\label{newmain}
For a commutative triple $\mathcal{T}=(A,B,\varepsilon)$, we have that
$$HH_1(A,B,\varepsilon)\cong\Omega_{\mathcal{T}|\mathbbm{k}}^1\cong J/(J^2+\hat{J}).$$
